def calibrate(p):
    (u, v) = (p['u'], p['v'])
    (i, j) = np.triu_indices(len(u), 1)
    d = u[i] - u[j]
    scale = np.median((v[i] - v[j]) / np.where(abs(d) > 1e-10, d, np.inf), axis=0)
    offset = np.median(v - u * scale, axis=0)
    for _ in range(3):
        r = np.linalg.norm(v - u * scale - offset, axis=1)
        keep = r < max(6 * np.median(r), 0.0005)
        if keep.sum() < 6:
            break
        for j in range(u.shape[1]):
            (scale[j], offset[j]) = np.linalg.lstsq(np.c_[u[keep, j], np.ones(keep.sum())], v[keep, j], rcond=None)[0]
    return (scale, offset)

def _chart(z, mode, h):
    if mode == 1:
        return np.arcsinh(h * z) / h
    if mode == 2:
        return z / (1 + h * abs(z))
    if mode == 3:
        return np.sign(z) * np.log1p(h * abs(z)) / h
    if mode == 4:
        return z / (1 + h * z * z)
    return z

def _prediction(C, i, j, y, r):
    from scipy.linalg import cho_factor
    from scipy.linalg import cho_solve
    return C[np.ix_(j, i)] @ cho_solve(cho_factor(C[np.ix_(i, i)] + r * np.eye(len(i))), y)
